// Firmware keycodes: keycap labels and the key palettes of the editor.
// Codes are what the keyboard stores (QMK-style, 16 bit). The NuPhy-specific values
// (0x78xx lighting, 0x7exx functions) were read from the NuPhyIO web app's converter.
"use strict";

const Keys = (() => {
  // Base labels; [shifted, plain] pairs are drawn on two lines like a real keycap.
  const BASE = {
    0x28: "ENTER", 0x29: "ESC", 0x2a: "BACKSPACE", 0x2b: "TAB", 0x2c: "SPACE",
    0x2d: ["_", "-"], 0x2e: ["+", "="], 0x2f: ["{", "["], 0x30: ["}", "]"], 0x31: ["|", "\\"],
    0x32: "NUHS", 0x33: [":", ";"], 0x34: ["\"", "'"], 0x35: ["~", "`"], 0x36: ["<", ","],
    0x37: [">", "."], 0x38: ["?", "/"], 0x39: "CAPS", 0x46: "PRTSC", 0x47: "SCR", 0x48: "PAUSE",
    0x49: "INS", 0x4a: "HOME", 0x4b: "PGUP", 0x4c: "DEL", 0x4d: "END", 0x4e: "PGDN",
    0x4f: "→", 0x50: "←", 0x51: "↓", 0x52: "↑", 0x53: "NUM", 0x54: "÷", 0x55: "×", 0x56: "-",
    0x57: "+", 0x58: "NUM\nENTER", 0x62: "0", 0x63: ".", 0x64: "NUBS", 0x65: "MENU",
    0x87: "RO", 0x88: "かな", 0x89: "¥", 0x8a: "變換", 0x8b: "無変換", 0x90: "한영", 0x91: "漢字",
    0xe0: "CTRL", 0xe1: "SHIFT", 0xe4: "CTRL", 0xe5: "SHIFT",
    // media / system (QMK basic range)
    0xa5: "POWER", 0xa6: "SLEEP", 0xa7: "WAKE", 0xa8: "MUTE", 0xa9: "VOL+", 0xaa: "VOL-",
    0xab: "NEXT", 0xac: "PREV", 0xad: "STOP", 0xae: "PLAY", 0xaf: "PLAYER", 0xb0: "EJECT",
    0xb1: "MAIL", 0xb2: "CALC", 0xb3: "PC", 0xb4: "WEB\nSEARCH", 0xb5: "WEB\nHOME",
    0xb6: "WEB\nBACK", 0xb7: "WEB\nFWD", 0xb8: "WEB\nSTOP", 0xb9: "WEB\nREFRESH", 0xba: "WEB\nFAV",
    0xbb: "FFWD", 0xbc: "REW", 0xbd: "SCREEN\nBRIGHT+", 0xbe: "SCREEN\nBRIGHT-",
    // mouse
    0xd1: "MOUSE\nLEFT", 0xd2: "MOUSE\nRIGHT", 0xd3: "MOUSE\nMIDDLE", 0xd4: "MOUSE\nBACK",
    0xd5: "MOUSE\nFWD", 0xd9: "WHEEL\nUP", 0xda: "WHEEL\nDOWN", 0xdb: "WHEEL\nLEFT", 0xdc: "WHEEL\nRIGHT",
    // NuPhy lighting
    0x7821: "RGB\nMODE", 0x7822: "RGB\nMODE-", 0x7823: "COLOR+", 0x7824: "COLOR-",
    0x7827: "BRIGHT+", 0x7828: "BRIGHT-", 0x7829: "SPEED+", 0x782a: "SPEED-",
    0x7e18: "LIGHT\nOFF", 0x7e19: "RGB\nTEST", 0x7e1b: "COLOR", 0x7e1c: "BRIGHT", 0x7e1d: "SPEED",
    0x7e1f: "LIGHT\nLEFT", 0x7e20: "LIGHT\nRIGHT", 0x7e21: "LIGHT\nTREND",
    0x7e0d: "SIDE\nBRIGHT+", 0x7e0e: "SIDE\nBRIGHT-", 0x7e0f: "SIDE\nMODE", 0x7e10: "SIDE\nCOLOR",
    0x7e11: "SIDE\nSPEED+", 0x7e12: "SIDE\nSPEED-", 0x7e3b: "CAPS\nLIGHT", 0x7e3c: "SIDE\nLIGHT",
    // NuPhy functions
    0x7e00: "BOOT", 0x7e01: "USB", 0x7e02: "2.4G", 0x7e03: "BT1", 0x7e04: "BT2", 0x7e05: "BT3",
    0x7e06: "MISSION\nCTRL", 0x7e07: "SEARCH", 0x7e08: "SIRI", 0x7e09: "LAUNCH\nPAD",
    0x7e0a: "PRT\nALL", 0x7e0b: "PRT\nAREA", 0x7e0c: "GLOBE", 0x7e13: "RESET", 0x7e14: "SLEEP",
    0x7e15: "BATTERY", 0x7e16: "DND", 0x7e1e: "WIN\nLOCK", 0x7c59: "KEYS\nLOCK", 0x7e3d: "FN\nLOCK",
    0x7e40: "WIN LOCK\nSCREEN", 0x7e41: "MAC LOCK\nSCREEN", 0x7e42: "FINDER", 0x7e43: "FORCE\nQUIT",
    0x7e44: "EMOJI", 0x7e45: "SHOW\nDESKTOP", 0x7e46: "TASK\nMANAGER", 0x7e47: "TOUCH\nSWITCH",
    0x7e48: "DESKTOP\n←", 0x7e49: "DESKTOP\n→", 0x7e4a: "SPACE\n←", 0x7e4b: "SPACE\n→",
    0x7e4c: "WIN APP\n←", 0x7e4d: "WIN APP\n→", 0x7e4e: "MAC APP\n←", 0x7e4f: "MAC APP\n→",
    0x7e50: "TASK\nVIEW", 0x7e51: "SNAP\n←", 0x7e52: "SNAP\n→", 0x7e53: "MAC\nDESKTOP",
    0x7e54: "INPUT\nSWITCH", 0x7e55: "DICTATE"
  };
  for (let i = 0; i < 26; i++) BASE[0x04 + i] = String.fromCharCode(65 + i);
  "!@#$%^&*()".split("").forEach((s, i) => { BASE[0x1e + i] = [s, String((i + 1) % 10)]; });
  for (let i = 0; i < 12; i++) BASE[0x3a + i] = "F" + (i + 1);
  for (let i = 0; i < 12; i++) BASE[0x68 + i] = "F" + (i + 13);
  for (let i = 0; i < 9; i++) BASE[0x59 + i] = String(i + 1);

  const MAC = { 0xe2: "OPT", 0xe3: "CMD", 0xe6: "OPT", 0xe7: "CMD" };
  const WIN = { 0xe2: "ALT", 0xe3: "WIN", 0xe6: "ALT", 0xe7: "WIN" };

  /** Keycap text for a code: a string (may contain "\n") or [shifted, plain]. */
  function cap(code, mac, fallback) {
    if (code === 0) return "";
    if (code === 1) return "▽";
    const m = (mac ? MAC : WIN)[code];
    if (m) return m;
    if (code in BASE) return BASE[code];
    if ((code & 0xfff0) === 0x5220) return "FN" + (code & 0xf);
    return fallback || hex(code);
  }
  const hex = c => "0x" + c.toString(16).padStart(4, "0");
  /** One-line text for toasts and search. */
  function text(code, mac, fallback) {
    const c = cap(code, mac, fallback);
    if (code === 0) return "NO";
    if (code === 1) return "TRNS";
    return Array.isArray(c) ? c[1] : c.replace("\n", " ");
  }

  // Basic palette: a full-size keyboard. [code, x, y, w, h]
  const FULL = [];
  const row = (y, x0, items) => { let x = x0; for (const it of items) { const [c, w = 1, h = 1] = [].concat(it); if (c != null) FULL.push([c, x, y, w, h]); x += w; } };
  row(0, 0, [0x29, ...range(0x3a, 12), 0x46, 0x4c]);
  row(0, 16.25, [0x4a, 0x4d, 0x4b, 0x4e]);
  row(1, 0, [0x35, ...range(0x1e, 10), 0x2d, 0x2e, [0x2a, 2]]);
  row(1, 16.25, [0x53, 0x54, 0x55, 0x56]);
  row(2, 0, [[0x2b, 1.5], 0x14, 0x1a, 0x08, 0x15, 0x17, 0x1c, 0x18, 0x0c, 0x12, 0x13, 0x2f, 0x30, [0x31, 1.5]]);
  row(2, 16.25, [0x5f, 0x60, 0x61, [0x57, 1, 2]]);
  row(3, 0, [[0x39, 1.75], 0x04, 0x16, 0x07, 0x09, 0x0a, 0x0b, 0x0d, 0x0e, 0x0f, 0x33, 0x34, [0x28, 2.25]]);
  row(3, 16.25, [0x5c, 0x5d, 0x5e]);
  row(4, 0, [[0xe1, 2.25], 0x1d, 0x1b, 0x06, 0x19, 0x05, 0x11, 0x10, 0x36, 0x37, 0x38, [0xe5, 1.75], 0x52]);
  row(4, 16.25, [0x59, 0x5a, 0x5b, [0x58, 1, 2]]);
  row(5, 0, [[0xe0, 1.25], [0xe3, 1.25], [0xe2, 1.25], [0x2c, 4.75], 0xe6, 0xe7, 0x65, 0xe4, [null, 0.5], 0x50, 0x51, 0x4f]);
  row(5, 16.25, [[0x62, 2], 0x63]);
  function range(a, n) { return Array.from({ length: n }, (_, i) => a + i); }

  const COMMON = [0x49, 0x47, 0x48, 0x65, 0x7821, 0x7828, 0x7827, 0x782a, 0x7829, 0x7e1b, 0xa9, 0xaa, 0xa8,
    0xae, 0xad, 0xac, 0xab, 0xbd, 0xbe, 0x7e1e, 0xb2, 0xb1, 0x01, 0x00];
  const MEDIA = [0xaf, 0xa9, 0xaa, 0xa8, 0xae, 0xad, 0xac, 0xab, 0xbd, 0xbe, 0xb5, 0xb9, 0xb8, 0xb6, 0xb7, 0xba,
    0xb4, 0xb3, 0xb2, 0xb1, 0x7e14, 0xb0, 0x7e15, 0x7e47, 0x7e48, 0x7e49, 0x7e4a, 0x7e4b, 0x7e4c, 0x7e4d,
    0x7e4e, 0x7e4f, 0x7e50, 0x7e51, 0x7e52, 0x7e0c, 0x7e40, 0x7e41, 0x7e42, 0x7e43, 0x7e44, 0x7e45, 0x7e46,
    0x7e53, 0x7e54, 0x7e55];
  const LIGHT = [0x7822, 0x7821, 0x7e19, 0x7828, 0x7827, 0x7e1c, 0x7e18, 0x782a, 0x7829, 0x7e1d, 0x7e1f, 0x7e20,
    0x7e21, 0x7823, 0x7824, 0x7e1b, 0x7e0d, 0x7e0e, 0x7e12, 0x7e11, 0x7e10, 0x7e0f, 0x7e3b, 0x7e3c];
  const SPECIAL = [0x01, 0x00, 0xd1, 0xd3, 0xd2, 0xd5, 0xd4, 0xd9, 0xda, 0xdb, 0xdc, 0x7e0b, 0x7e0a,
    0x7e06, 0x7e09, 0x7e08, 0x7e07, 0x7e16, 0x7e3d, 0x7e1e, 0x7c59, 0x7e01, 0x7e02, 0x7e03, 0x7e04, 0x7e05,
    0x32, 0x64, 0x87, 0x89, 0x8b, 0x91, 0x90, 0x8a, 0x88, 0x7e13, 0x7e00, ...range(0x68, 12)];

  /** Layer keys (MO) for the layers of one mode. */
  const layerKeys = (first, n) => range(0x5220 + first, n).filter(c => c <= 0x522f);

  return { cap, text, hex, FULL, COMMON, MEDIA, LIGHT, SPECIAL, layerKeys, range };
})();
